"""📝 Hand-written asset notes for author-64-decisions.py. ("body","50") = finest scale, ("body","C") = every coarser scale, ("thermal","all"), ("structure","all"), ("scale", s) = an extra entry for one scale."""
REWRITE_MINIMAL = set()
NOTES = {
    "animals/pig": {
        ("body", "50"): ("Every hoof is cloven into two toes of about 37 mm, the ears are flaps rolled out of the sagittal plane, the snout is a flattened disc of bare skin, the eyes are 15 mm balls and the curled tail is a loft of its own cut from the drawn curl.", "Jeder Huf ist in zwei Zehen von etwa 37 mm gespalten, die Ohren sind aus der Mittelebene gerollte Lappen, der Rüssel ist eine flache Scheibe nackter Haut, die Augen sind 15-mm-Kugeln und der Ringelschwanz ist ein eigener Loft aus der gezeichneten Locke."),
        ("body", "C"): ("The barrel trunk stays hindbody and chest masses with a neck wedge and the legs stay one loft per drawn segment; whatever falls below the feature of the scale (cloven toes, eyes, jaw, ear flaps) is folded into the neighbouring mass.", "Der Fassrumpf bleibt Hinterkörper- und Brustmasse mit Halskeil und die Beine bleiben je ein Loft pro gezeichnetem Abschnitt; was unter die kleinste Einzelheit des Maßstabs fällt (gespaltene Zehen, Augen, Kiefer, Ohrlappen), geht in der Nachbarmasse auf."),
        ("body", "500"): ("The legs are cut from the elevation redrawn at the root for this scale and are at least 75 mm thick; ears, hooves, snout and tail have no body solid and live as thermal solids only.", "Die Beine sind aus dem für diesen Maßstab an der Wurzel neu gezeichneten Aufriss geschnitten und mindestens 75 mm dick; Ohren, Hufe, Rüssel und Schwanz haben keinen Körper und bestehen nur als Thermikkörper."),
    },
    "animals/sheep": {
        ("body", "50"): ("Each hoof is two toes, the ears are rolled flaps, the thick fleece is carried by the trunk lofts (hindbody, chest, neck) and the short tail is a root loft and a tip loft; the eyes are separate balls in the head sides.", "Jeder Huf besteht aus zwei Zehen, die Ohren sind gerollte Lappen, das dicke Vlies tragen die Rumpflofts (Hinterkörper, Brust, Hals), der kurze Schwanz besteht aus Wurzel- und Spitzenloft; die Augen sind eigene Kugeln in den Kopfseiten."),
        ("body", "C"): ("The fleece outline decides the trunk: hindbody, chest and neck stay three overlapping masses and the legs thin to gaskin, cannon and hoof lofts; whatever the drawing no longer separates is folded into its neighbour.", "Der Vliesumriss bestimmt den Rumpf: Hinterkörper, Brust und Hals bleiben drei sich überlappende Massen, und die Beine werden zu Unterschenkel-, Röhrbein- und Huflofts; was die Zeichnung nicht mehr trennt, geht in der Nachbarmasse auf."),
    },
    "animals/red-fox": {
        ("body", "50"): ("The fox is drawn with a pointed face (head loft, jaw, nose and two eyes), two upright ears, a brush in three parts (root, middle, tip) and thin digitigrade legs that end in paws.", "Der Fuchs ist mit spitzem Gesicht (Kopfloft, Kiefer, Nase, zwei Augen), zwei aufrechten Ohren, dreiteiliger Lunte (Wurzel, Mitte, Spitze) und dünnen Zehengängerbeinen mit Pfoten gezeichnet."),
        ("body", "C"): ("The brush stays three lofts because the drawings still read it as a long taper, and the legs stay one loft per drawn segment; the face details that the scale cannot show are merged into the head loft.", "Die Lunte bleibt in drei Lofts, weil die Zeichnungen sie weiterhin als langen Kegel lesen, und die Beine bleiben je ein Loft pro gezeichnetem Abschnitt; die Gesichtsdetails, die der Maßstab nicht zeigen kann, gehen im Kopfloft auf."),
    },
    "animals/red-squirrel": {
        ("body", "50"): ("The squirrel is a sitting animal of rump, chest, neck and head with a two-part bushy tail, near and far arm, forearm and hand, near and far thigh, shank and foot, two ears, two eyes, a nose and a belly patch of lighter fur.", "Das Eichhörnchen ist ein sitzendes Tier aus Gesäß, Brust, Hals und Kopf mit zweiteiligem buschigem Schwanz, nahem und fernem Arm, Unterarm und Hand, nahem und fernem Oberschenkel, Unterschenkel und Fuß, zwei Ohren, zwei Augen, einer Nase und einem Bauchfleck aus hellerem Fell."),
        ("body", "100"): ("Arms, hands, thighs and feet are carried by the rump and chest masses, so only rump, chest, neck, head, the two tail lofts, the two ears and the nose remain, and the sitting silhouette comes from the tail and the body masses.", "Arme, Hände, Oberschenkel und Füße gehen in den Gesäß- und Brustmassen auf, es bleiben nur Gesäß, Brust, Hals, Kopf, die zwei Schwanzlofts, die zwei Ohren und die Nase, und die Sitzsilhouette entsteht aus Schwanz und Körpermassen."),
    },
    "animals/horse": {
        ("body", "50"): ("The horse has a three-part neck, a tail of four segments, a mane of three tufts with a forelock, and on each leg the full chain from scapula or thigh over radius or gaskin, cannon and pastern to the hoof; muzzle, jaw, two ears and two eyes are separate solids.", "Das Pferd hat einen dreiteiligen Hals, einen Schweif aus vier Segmenten, eine Mähne aus drei Büscheln mit Schopf und an jedem Bein die ganze Kette von Schulterblatt bzw. Oberschenkel über Speiche bzw. Unterschenkel, Röhrbein und Fessel bis zum Huf; Maul, Kiefer, zwei Ohren und zwei Augen sind eigene Körper."),
        ("body", "C"): ("The leg chain is shortened from its lower end first (hooves, pasterns, scapula), the mane tufts are folded into fewer masses and the neck loses a section, while the four tail segments stay because the tail hangs as a long drawn taper.", "Die Beinkette wird zuerst am unteren Ende gekürzt (Hufe, Fesseln, Schulterblatt), die Mähnenbüschel gehen in weniger Massen auf und der Hals verliert einen Abschnitt, während die vier Schweifsegmente bleiben, weil der Schweif als langer gezeichneter Kegel hängt."),
    },
    "animals/dairy-cow": {
        ("body", "50"): ("The cow carries an udder with four teats, three patch lofts (rump, barrel, chest) and a rumen flank bulge on its trunk, a three-part tail, a muzzle, a jaw, two ears and two eyes, and four legs from thigh or scapula down to the hoof.", "Die Kuh trägt am Rumpf ein Euter mit vier Zitzen, drei Fleckenlofts (Becken, Rumpf, Brust) und die Pansenwölbung der Flanke, dazu einen dreiteiligen Schwanz, Maul, Kiefer, zwei Ohren und zwei Augen sowie vier Beine von Oberschenkel bzw. Schulterblatt bis zum Huf."),
        ("body", "C"): ("The udder stays as its own mass because it is drawn below the belly, the tail stays three lofts and the legs stay one loft per drawn segment; patches, teats, muzzle and eyes are not drawn at these scales and are folded into the trunk and head.", "Das Euter bleibt als eigene Masse, weil es unter dem Bauch gezeichnet ist, der Schwanz bleibt in drei Lofts und die Beine bleiben je ein Loft pro gezeichnetem Abschnitt; Flecken, Zitzen, Maul und Augen sind in diesen Maßstäben nicht gezeichnet und gehen in Rumpf und Kopf auf."),
        ("body", "500"): ("The two ears are one ear span, and the hooves and the jaw have no solid of their own any more.", "Die beiden Ohren sind eine Ohrenspanne, und Hufe und Kiefer haben keinen eigenen Körper mehr."),
    },
    "animals/labrador-dog": {
        ("body", "50"): ("The labrador has a skull block with a jaw, a tongue and a nose leather, two ears and two eyes, a three-part tapering otter tail, legs with thigh, shank, hock and paw behind and scapula, humerus, forearm, wrist and forepaw in front, and four pads under the paws.", "Der Labrador hat einen Schädelblock mit Kiefer, Zunge und Nasenleder, zwei Ohren und zwei Augen, eine dreiteilige konische Otterrute, Beine mit Oberschenkel, Unterschenkel, Sprunggelenk und Pfote hinten sowie Schulterblatt, Oberarm, Unterarm, Handwurzel und Vorderpfote vorn und vier Ballen unter den Pfoten."),
        ("body", "C"): ("The long-boned leg chain (thigh, shank, hock and humerus, forearm, wrist) stays until 1:500 because the dog's legs are drawn as thin separate shapes; paws, pads, tongue, nose leather and eyes are merged as soon as they fall below the feature.", "Die langknochige Beinkette (Oberschenkel, Unterschenkel, Sprunggelenk bzw. Oberarm, Unterarm, Handwurzel) bleibt bis 1:500, weil die Beine des Hundes als dünne einzelne Formen gezeichnet sind; Pfoten, Ballen, Zunge, Nasenleder und Augen gehen auf, sobald sie unter die kleinste Einzelheit fallen."),
    },
    "humans/walking-commuter": {
        ("body", "50"): ("The commuter is dressed in layers: a coat on torso, arms and pelvis, trousers on thighs and shanks, a scarf at the neck, shoe uppers and soles, hands with four fingers and their tips and a thumb, ears, eyes, hair and a shoulder bag; the bare skin lies under each garment as its own shell and caps close the cut ends of sleeves and trouser legs.", "Der Pendler ist in Schichten gekleidet: Mantel an Rumpf, Armen und Becken, Hose an Oberschenkeln und Unterschenkeln, Schal am Hals, Schuhobermaterial und Sohlen, Hände mit vier Fingern samt Kuppen und Daumen, Ohren, Augen, Haar und eine Umhängetasche; die nackte Haut liegt unter jedem Kleidungsstück als eigene Schale, und Kappen schließen die offenen Enden von Ärmeln und Hosenbeinen."),
        ("body", "C"): ("The coat sleeves, trouser legs, scarf or neck mass and the shoulder bag carry the silhouette; the skin shells, fingers, eyes and ears that the drawings of this scale no longer show are merged into their garment or limb loft.", "Mantelärmel, Hosenbeine, Schal- bzw. Halsmasse und Umhängetasche tragen die Silhouette; die Hautschalen, Finger, Augen und Ohren, die die Zeichnungen dieses Maßstabs nicht mehr zeigen, gehen im Kleidungs- oder Gliedmaßenloft auf."),
    },
    "humans/standing-phone-user": {
        ("body", "50"): ("The phone user wears a hoodie (torso, hood, rib hem, sleeves with rib cuffs), jeans and sneakers with soles and high-top parts, headphone cups, a phone in the hand, hair, ears and eyes; the hands carry four fingers and a thumb and the skin sits under the clothing as shells.", "Die Person mit Telefon trägt einen Kapuzenpullover (Rumpf, Kapuze, Rippsaum, Ärmel mit Rippbündchen), Jeans und Turnschuhe mit Sohlen und Schaftteilen, Kopfhörermuscheln, ein Telefon in der Hand, Haar, Ohren und Augen; die Hände tragen vier Finger und einen Daumen, und die Haut liegt als Schalen unter der Kleidung."),
        ("body", "C"): ("The hoodie, the jeans and the head with hair carry the silhouette; fingers, eyes, ears, cuffs, hem rib and skin shells are folded into their garment loft, while headphone cups and phone stay as long as they are drawn.", "Pullover, Jeans und der Kopf mit Haar tragen die Silhouette; Finger, Augen, Ohren, Bündchen, Rippsaum und Hautschalen gehen im Kleidungsloft auf, während Kopfhörermuscheln und Telefon bleiben, solange sie gezeichnet sind."),
    },
    "humans/sleeping-person": {
        ("body", "50"): ("The sleeper lies on the side under a duvet with a pillow: torso, pelvis, thigh, shank, arm and forearm lofts in the tone of the nightwear, hair, head and neck, the hands with four fingers and a thumb, feet and toes, skin shells where limbs show and two duvet skirts (over the torso and over the legs).", "Die schlafende Person liegt seitlich unter einer Decke mit Kissen: Rumpf-, Becken-, Oberschenkel-, Unterschenkel-, Arm- und Unterarmlofts im Ton der Nachtwäsche, Haar, Kopf und Hals, die Hände mit vier Fingern und Daumen, Füße und Zehen, Hautschalen dort, wo Gliedmaßen frei liegen, und zwei Deckensäume (über Rumpf und über den Beinen)."),
        ("body", "C"): ("The pillow and the two duvet skirts carry the silhouette of a lying person under a cover; the body is reduced to torso, pelvis, leg and arm masses and the fingers, skin shells and neck skin are folded into them.", "Das Kissen und die zwei Deckensäume tragen die Silhouette einer zugedeckten liegenden Person; der Körper schrumpft auf Rumpf-, Becken-, Bein- und Armmassen, in denen Finger, Hautschalen und Halshaut aufgehen."),
    },
    "humans/parent-with-stroller": {
        ("body", "50"): ("The adult is a jointed figure of pelvis, torso, head with hair, arms, hands with fingers and thumb, legs, feet and toes, ears, eyes, brows, a mouth, jacket zips and a collar; the stroller is its own frame of handle, push bars, chassis, rear struts, front forks, footrest, seat fabric, hood and basket on two tyres with rims, carrying a child with body, legs, head, hat and arms.", "Der Erwachsene ist eine gegliederte Figur aus Becken, Rumpf, Kopf mit Haar, Armen, Händen mit Fingern und Daumen, Beinen, Füßen und Zehen, Ohren, Augen, Brauen, Mund, Jackenreißverschlüssen und Kragen; der Kinderwagen ist ein eigener Rahmen aus Griff, Schubstangen, Fahrgestell, Hinterstreben, Vordergabeln, Fußstütze, Sitzstoff, Verdeck und Korb auf zwei Reifen mit Felgen und trägt ein Kind mit Körper, Beinen, Kopf, Mütze und Armen."),
        ("body", "C"): ("The adult keeps pelvis, torso, head and the leg chain while face details, zips and fingers fall away; the stroller is carried by its frame, wheels and canopy, with the child as one or a few masses inside.", "Der Erwachsene behält Becken, Rumpf, Kopf und die Beinkette, während Gesichtsdetails, Reißverschlüsse und Finger entfallen; der Kinderwagen wird von Rahmen, Rädern und Verdeck getragen, mit dem Kind als einer oder wenigen Massen darin."),
    },
    "humans/person-cooking": {
        ("body", "50"): ("The cook stands at a kitchen counter (plinth, body, panel, worktop) with a hob plate, two burner rings, a pot with a handle and a spoon with a bowl; the figure wears a hoodie with hood, collar rib, hem rib, kangaroo pocket and drawstrings, jeans with hems and shoes with soles.", "Die kochende Person steht an einer Küchenzeile (Sockel, Korpus, Front, Arbeitsplatte) mit Kochfeld, zwei Brennerringen, Topf mit Griff und Löffel mit Laffe; die Figur trägt einen Kapuzenpullover mit Kapuze, Kragenrippe, Saumrippe, Känguru-Tasche und Kordeln, Jeans mit Säumen und Schuhe mit Sohlen."),
        ("body", "C"): ("The counter shrinks to fewer blocks and, at 1:500, to one silhouette block; pot and spoon each become one solid, and the cook loses drawstrings, pocket, collar, hems and the face details.", "Die Küchenzeile schrumpft auf weniger Blöcke und bei 1:500 auf einen Silhouettenblock; Topf und Löffel werden je ein Körper, und die Person verliert Kordeln, Tasche, Kragen, Säume und die Gesichtsdetails."),
    },
    "humans/person-with-rollator": {
        ("body", "50"): ("The rollator is modelled bar by bar (rear uprights, front legs, lower and seat rails, front brace, backrest arms, caster forks, brake levers and cables, handlebar and grips, seat, backrest, basket tub and wire, bag, four tyres with rims and hubs) in front of an elderly figure in coat, trousers, beret and shoes with all layers and skin shells.", "Der Rollator ist Stab für Stab modelliert (Hinterholme, Vorderbeine, Unter- und Sitzstreben, Frontstrebe, Rückenlehnenarme, Lenkgabeln, Bremshebel und Seile, Lenker und Griffe, Sitz, Rückenlehne, Korbwanne und Draht, Tasche, vier Reifen mit Felgen und Naben) vor einer älteren Figur in Mantel, Hose, Baskenmütze und Schuhen mit allen Schichten und Hautschalen."),
        ("body", "C"): ("The frame stays as four legs, rails, handlebar, grips, seat and basket tub; brake parts, wires, hubs and rims fall away, each wheel becomes one solid at 1:200 and 1:500, and coat, trousers and beret shrink to about one mass per body part.", "Der Rahmen bleibt als vier Beine, Streben, Lenker, Griffe, Sitz und Korbwanne; Bremsteile, Drähte, Naben und Felgen entfallen, jedes Rad wird bei 1:200 und 1:500 ein Körper, und Mantel, Hose und Baskenmütze schrumpfen auf etwa eine Masse je Körperteil."),
    },
    "humans/standing-adult": {
        ("body", "50"): ("The standing adult is a hooded figure: head with hair, nose, ears and eyes, neck, hood, torso and pelvis lofts, arms with forearms, hands and thumbs, thighs, shanks, shoes with soles and toes, cuffs and a hem.", "Der stehende Erwachsene ist eine Figur mit Kapuze: Kopf mit Haar, Nase, Ohren und Augen, Hals, Kapuze, Rumpf- und Beckenlofts, Arme mit Unterarmen, Händen und Daumen, Oberschenkel, Unterschenkel, Schuhe mit Sohlen und Zehen, Bündchen und ein Saum."),
        ("body", "C"): ("The figure is reduced to plain lofts per limb segment, head, neck, torso and pelvis; face details, thumbs, cuffs, soles and the hem are merged into their parent lofts.", "Die Figur schrumpft auf schlichte Lofts je Gliedmaßenabschnitt, Kopf, Hals, Rumpf und Becken; Gesichtsdetails, Daumen, Bündchen, Sohlen und der Saum gehen in ihren Elternlofts auf."),
    },
    "humans/runner-with-blade-prosthesis": {
        ("body", "50"): ("The runner has a blade prosthesis on one leg (a socket with trim and pyramid adapter, bolt, upper blade, curl and toe) and a shoe with toe and sole on the other; the upper body shows a singlet with hem and bib, shoulders, arms, hands, thumbs, hair, ears, eyes and a nose.", "Die Läuferin bzw. der Läufer hat an einem Bein eine Klingenprothese (Schaft mit Rand und Pyramidenadapter, Bolzen, obere Klinge, Kurve und Spitze) und am anderen Bein einen Schuh mit Spitze und Sohle; der Oberkörper zeigt ein Trägershirt mit Saum und Startnummer, Schultern, Arme, Hände, Daumen, Haar, Ohren, Augen und eine Nase."),
        ("body", "C"): ("The blade keeps its upper part and curl because the curve is what the drawings show; bolt, adapter details, bib, hem, eyes, ears and thumbs are merged into their parent solids as the scale grows.", "Die Klinge behält ihren oberen Teil und die Kurve, weil die Kurve das ist, was die Zeichnungen zeigen; Bolzen, Adapterdetails, Startnummer, Saum, Augen, Ohren und Daumen gehen mit wachsendem Maßstab in ihren Elternkörpern auf."),
    },
    "humans/pregnant-person": {
        ("body", "50"): ("The pregnant person wears a sweater with a ribbed hem and boots with soles and toes; the belly is its own loft, shoulders, elbows and knees are joint solids, and hair, ears, eyes and a nose are drawn on the head.", "Die schwangere Person trägt einen Pullover mit Rippsaum und Stiefel mit Sohlen und Zehen; der Bauch ist ein eigener Loft, Schultern, Ellbogen und Knie sind Gelenkkörper, und am Kopf sind Haar, Ohren, Augen und eine Nase gezeichnet."),
        ("body", "C"): ("The belly stays its own mass at every scale because it is what the silhouette shows; face details, thumbs, the hem rib and the boot soles are merged away, and the joint solids fall into the limb lofts at the coarsest scale.", "Der Bauch bleibt in jedem Maßstab eine eigene Masse, weil ihn die Silhouette zeigt; Gesichtsdetails, Daumen, Rippsaum und Stiefelsohlen sind zusammengefasst, und die Gelenkkörper gehen im gröbsten Maßstab in den Gliedmaßenlofts auf."),
    },
    "vegetation/apple-tree": {
        ("plain", "all"): True,
        ("body", "50"): ("The apple tree is a trunk with a leader loft, eight scaffold limbs in two tiers (west and east, two per side and tier), seven foliage masses (a low and an upper core lobe, one lobe per side and tier, a top lobe) and five fruit clusters.", "Der Apfelbaum besteht aus Stamm mit Mittelastloft, acht Leitästen in zwei Etagen (West und Ost, je zwei pro Seite und Etage), sieben Laubmassen (einem unteren und einem oberen Kernlappen, je einem Lappen pro Seite und Etage, einem Gipfellappen) und fünf Fruchtbüscheln."),
        ("body", "100"): ("Limbs and foliage masses are the same as at 1:50 but re-cut from the 1:100 outline; the five fruit clusters stay separate solids because the drawing still shows them.", "Äste und Laubmassen sind dieselben wie bei 1:50, aber aus dem Umriss von 1:100 neu geschnitten; die fünf Fruchtbüschel bleiben eigene Körper, weil die Zeichnung sie noch zeigt."),
        ("body", "200"): ("The two second-tier limbs on the b side are folded into their neighbours and the five fruit clusters become one fruit-crown solid, while the seven foliage masses keep the scalloped crown outline.", "Die zwei Äste der zweiten Etage auf der b-Seite gehen in ihren Nachbarn auf und die fünf Fruchtbüschel werden ein Fruchtkronenkörper, während die sieben Laubmassen den gewellten Kronenumriss behalten."),
        ("body", "500"): ("Only the trunk, one crown loft (it stands for the leaf mass and carries the sun-leaf region) and one fruit-crown ellipsoid are body solids; limbs, spurs and shade foliage appear as thin thermal capsules only.", "Nur Stamm, ein Kronenloft (er steht für die Blattmasse und trägt die Sonnenblattregion) und ein Fruchtkronen-Ellipsoid sind Körper des Volumens; Äste, Fruchtspieße und Schattenlaub erscheinen nur als dünne Thermikkapseln."),
    },
    "vegetation/date-palm": {
        ("plain", "all"): True,
        ("body", "50"): ("The palm is built segment by segment: a root bulb, three stem segments with a ring solid per leaf-scar band, a crown shaft, four skirt masses, two fruit bunches on two stalks each, and per frond a rachis and a blade with plugs that close the loft ends; the fronds sit in pairs on both sides.", "Die Palme ist Segment für Segment gebaut: Wurzelknolle, drei Stammsegmente mit je einem Ringkörper pro Blattnarbenband, ein Kronenschaft, vier Rockmassen, zwei Fruchtstände an je zwei Stielen und je Wedel eine Rhachis und ein Fiederblatt mit Stopfen, die die Loftenden schließen; die Wedel sitzen paarweise auf beiden Seiten."),
        ("body", "100"): ("The three stem segments, their rings and the shaft are merged into one bole with small stem and crown solids, a crown bud and a crown heart; every frond keeps a rachis and a blade and the bunches lose their stalks.", "Die drei Stammsegmente, ihre Ringe und der Schaft sind zu einem Stamm zusammengefasst mit kleinen Stamm- und Kronenkörpern, Kronenknospe und Kronenherz; jeder Wedel behält Rhachis und Fiederblatt, und die Fruchtstände verlieren ihre Stiele."),
        ("body", "200"): ("Of each pair of fronds only the first keeps its rachis, the second is a blade alone; the bole keeps three ring solids and the crown bud, the bunches are two solids.", "Von jedem Wedelpaar behält nur der erste seine Rhachis, der zweite ist ein Fiederblatt allein; der Stamm behält drei Ringkörper und die Kronenknospe, die Fruchtstände sind zwei Körper."),
        ("body", "500"): ("The palm is a bole, one crown mass and two fruit bunches.", "Die Palme besteht aus Stamm, einer Kronenmasse und zwei Fruchtständen."),
    },
    "vegetation/bamboo-clump": {
        ("plain", "all"): True,
        ("body", "50"): ("The clump is six culms of three stem segments each with top and base caps, a sun and a shade leaf mass per culm, and two fans (a and b) of foliage plates cut into sun and shade slices.", "Der Horst besteht aus sechs Halmen mit je drei Halmsegmenten samt Kopf- und Fußkappen, einer Sonnen- und einer Schattenlaubmasse je Halm und zwei Fächern (a und b) aus Laubplatten, geschnitten in Sonnen- und Schattenscheiben."),
        ("body", "100"): ("The six culms keep their three segments, while the foliage plates are re-cut as sprays (a and b) and fewer culm tops and bases are drawn.", "Die sechs Halme behalten ihre drei Segmente, während die Laubplatten als Sprays (a und b) neu geschnitten werden und weniger Halmköpfe und -füße gezeichnet sind."),
        ("body", "200"): ("The six culms stay as three segments each, but the leaf masses merge from sun and shade pairs per culm into a few masses (two culm groups and two shared sprays).", "Die sechs Halme bleiben bei je drei Segmenten, aber die Laubmassen gehen von Sonnen- und Schattenpaaren je Halm in wenige Massen auf (zwei Halmgruppen und zwei gemeinsame Sprays)."),
        ("body", "500"): ("The clump is one stems block and two crown masses.", "Der Horst besteht aus einem Halmblock und zwei Kronenmassen."),
    },
    "vegetation/hosta-clump": {
        ("plain", "all"): True,
        ("body", "50"): ("The hosta is a rosette of nine leaves (four pairs on the right and left plus a centre leaf), each as a blade, a midrib and a petiole.", "Die Funkie ist eine Rosette aus neun Blättern (vier Paare rechts und links plus ein Mittelblatt), jedes aus Spreite, Mittelrippe und Blattstiel."),
        ("body", "100"): ("Each leaf is a blade and a petiole; the midribs are merged into the blades.", "Jedes Blatt besteht aus Spreite und Blattstiel; die Mittelrippen sind in den Spreiten aufgegangen."),
        ("body", "200"): ("The rosette is three masses: an outer left, an outer right and an inner mass; single blades and petioles are no longer drawn.", "Die Rosette besteht aus drei Massen: einer äußeren linken, einer äußeren rechten und einer inneren Masse; einzelne Spreiten und Blattstiele sind nicht mehr gezeichnet."),
    },
    "humans/person-with-white-cane": {
        ("body", "50"): ("The figure is a woman in jacket and jeans with sunglasses (two lenses, a bridge and two arms), a shoulder bag with strap and flap, a collar at the neck, shoe uppers with soles and toes, hands with a thumb each and the long white cane held out in front: its shaft, a coloured band, the grip, six strap segments, the ferrule and the rolling tip.", "Die Figur ist eine Frau in Jacke und Jeans mit Sonnenbrille (zwei Gläser, Steg und zwei Bügel), Umhängetasche mit Gurt und Klappe, Kragen am Hals, Schuhoberteilen mit Sohlen und Zehen, Händen mit je einem Daumen und dem langen weißen Stock, den sie vor sich hält: Schaft, Farbband, Griff, sechs Schlaufenglieder, Zwinge und Rollspitze."),
        ("body", "C"): ("The jacket, jeans, head, neck, collar and bag carry the silhouette, and the cane stays a shaft with grip and tip at every scale because it is the one part that tells the figure's story; sunglasses, strap segments, thumbs and shoe details are folded into their parent solids as the feature grows.", "Jacke, Jeans, Kopf, Hals, Kragen und Tasche tragen die Silhouette, und der Stock bleibt in jedem Maßstab Schaft mit Griff und Spitze, weil er das einzige Teil ist, das die Geschichte der Figur erzählt; Sonnenbrille, Schlaufenglieder, Daumen und Schuhdetails gehen mit wachsender Einzelheit in ihren Elternkörpern auf."),
    },
    "vegetation/english-oak": {
        ("plain", "all"): True,
        ("body", "50"): ("The oak is built from lofts: a root plate, a trunk in two lofts, a leader with a top, west and east limbs on a low and a mid tier with their secondary branches, foliage masses with a cross loft per limb and a core mass, and four crown-fill lofts that close the gaps of the scalloped crown.", "Die Eiche besteht aus Lofts: einer Wurzelplatte, einem Stamm aus zwei Lofts, einem Mittelast mit Spitze, West- und Ostästen auf einer unteren und einer mittleren Etage mit ihren Nebenästen, Laubmassen mit je einem Querloft pro Ast und einer Kernmasse sowie vier Kronenfüllungslofts, die die Lücken der gewellten Krone schließen."),
        ("body", "C"): ("Branches and root plate are folded into the limbs and the trunk as the feature grows, while the crown keeps the foliage masses that carry its scalloped outline; at the coarsest scale only the trunk, the two lower limbs and one leader mass are left.", "Nebenäste und Wurzelplatte gehen mit wachsender Einzelheit in den Ästen und im Stamm auf, während die Krone die Laubmassen behält, die ihren gewellten Umriss tragen; im gröbsten Maßstab bleiben nur Stamm, die zwei unteren Äste und eine Mittelastmasse."),
    },
    "vegetation/agave": {
        ("plain", "all"): True,
        ("body", "50"): ("The agave is a caudex with a central spear and a rosette of eighteen leaves in two ranks (right and left, each with four pairs a and b and a single fifth leaf), every leaf a loft of its own in the frame of its bone.", "Die Agave besteht aus einem Caudex mit einem zentralen Speer und einer Rosette aus achtzehn Blättern in zwei Reihen (rechts und links, je vier Paare a und b und ein einzelnes fünftes Blatt), jedes Blatt ein eigener Loft im Rahmen seiner Bone."),
        ("body", "C"): ("The rosette keeps one loft per leaf or blade, with fewer sections per leaf and a leaf thickness that is raised to the feature of the scale, because the 2D drawings still draw the leaves one by one.", "Die Rosette behält einen Loft je Blatt bzw. Spreite, mit weniger Schnitten je Blatt und einer Blattdicke, die auf die Einzelheit des Maßstabs angehoben ist, weil die Zeichnungen die Blätter weiterhin einzeln zeichnen."),
    },
}
